import { useRef, type ReactNode } from "react";
import {
  createSortedRowModel, flexRender, rowSortingFeature, sortFns, tableFeatures,
  useTable, type ColumnDef, type Row, type RowData,
} from "@tanstack/react-table";
import {
  FlatList, Pressable, ScrollView, Text, View, type ViewProps,
} from "react-native";
import { createStore, type StoreApi } from "zustand/vanilla";
import { useStore } from "zustand";
import { joinClasses } from "@/components/nyc-tron/ui/components/styles";
import { dataTableLayout, tableContentWidth, type DataTableLayout } from "@/components/nyc-tron/ui/components/data/table-layout";

/** TanStack owns row/column logic; NYC-Tron owns actual RN rendering. */
const features = tableFeatures({
  rowSortingFeature, sortedRowModel: createSortedRowModel(), sortFns,
});
export type TronColumnDef<T extends RowData> = ColumnDef<typeof features, T, unknown>;
export interface DataTableProps<T extends RowData> extends Omit<ViewProps, "children"> {
  readonly data: readonly T[];
  readonly columns: TronColumnDef<T>[];
  readonly getRowId?: (row: T) => string;
  readonly onRowPress?: (row: T) => void;
  /** Optional measured width. When absent, onLayout tracks THIS host pane. */
  readonly width?: number;
  /** 'cards' is mobile-friendly; 'table' preserves a horizontal column grid. */
  readonly layout?: DataTableLayout;
  readonly cardsBelow?: number;
  readonly minColumnWidth?: number;
  readonly getColumnLabel?: (columnId: string) => string;
  readonly renderCard?: (row: Row<typeof features, T>) => ReactNode;
  readonly rowHeight?: number;
  readonly headerHeight?: number;
  readonly maxHeight?: number;
  readonly emptyLabel?: string;
  readonly sortable?: boolean;
  readonly className?: string;
  readonly headerClassName?: string;
  readonly rowClassName?: string;
  readonly cellClassName?: string;
  readonly unstyled?: boolean;
}
type PaneSize = { width: number | null };

function asNativeNode(value: unknown, textClassName?: string): ReactNode {
  if (value === null || value === undefined || typeof value === "boolean") return null;
  return typeof value === "string" || typeof value === "number"
    ? <Text {...{ className: textClassName }}>{value}</Text>
    : value as ReactNode;
}
export function DataTable<T extends RowData>({
  data, columns, getRowId, onRowPress, width, layout = "auto",
  cardsBelow = 620, minColumnWidth = 144, getColumnLabel, renderCard,
  rowHeight = 44, headerHeight = 44, maxHeight = 640, emptyLabel = "No records",
  sortable = true, className, headerClassName, rowClassName, cellClassName,
  unstyled = false, onLayout, style, ...rest
}: DataTableProps<T>) {
  const sizeStoreRef = useRef<StoreApi<PaneSize> | null>(null);
  if (!sizeStoreRef.current) {
    sizeStoreRef.current = createStore<PaneSize>(() => ({ width: null }));
  }
  const store = sizeStoreRef.current;
  const measuredWidth = useStore(store, s => s.width);
  const availableWidth = width ?? measuredWidth;
  const displayMode = dataTableLayout({ layout, containerWidth: availableWidth, cardsBelow });
  const columnWidth = tableContentWidth(availableWidth, columns.length, minColumnWidth);

  const table = useTable({
    key: "nyc-tron-data-table", features, data: [...data], columns,
    ...(getRowId ? { getRowId } : {}),
  });
  const rows = table.getRowModel().rows;
  const headers = table.getHeaderGroups().at(-1)?.headers ?? [];
  const headerByColumn = new Map(headers.map(header => [header.column.id, header]));
  const labelFor = (id: string): string => {
    const custom = getColumnLabel?.(id);
    if (custom) return custom;
    const header = headerByColumn.get(id)?.column.columnDef.header;
    return typeof header === "string" && header.trim() ? header : id;
  };

  // RN Text does not inherit color from its parent View; without a token class
  // primitive values render in the platform default (black) on dark surfaces.
  const textClass = !unstyled ? "text-text" : undefined;
  const sortValue = (dir: false | "asc" | "desc") =>
    dir === "asc" ? "sorted ascending" : dir === "desc" ? "sorted descending" : "not sorted";

  const cardRow = (row: (typeof rows)[number]) => {
    if (renderCard) return renderCard(row);
    // Not `accessible`: grouping here would replace every field with one
    // "Record <id>" label and hide the values from screen readers.
    return (
      <View
        {...{ className: joinClasses(
          "gap-3 p-4", !unstyled && "rounded-card border border-border bg-surface-raised",
          rowClassName,
        ) }}>
        {row.getAllCells().map(cell => (
          <View key={cell.id} {...{ className: joinClasses("flex-row items-start gap-3", cellClassName) }}>
            <Text style={{ width: "40%", flexShrink: 0, fontWeight: "600" }}
              {...{ className: !unstyled ? "text-text-muted" : undefined }}>
              {labelFor(cell.column.id)}
            </Text>
            <View style={{ flex: 1, minWidth: 0 }}>
              {asNativeNode(flexRender(cell.column.columnDef.cell, cell.getContext()), textClass)}
            </View>
          </View>
        ))}
      </View>
    );
  };

  const sortingControls = sortable ? headers.filter(header =>
    !header.isPlaceholder && header.column.getCanSort()
  ) : [];
  const onHostLayout: ViewProps["onLayout"] = event => {
    const next = event.nativeEvent.layout.width;
    if (Number.isFinite(next) && next >= 0 && store.getState().width !== next) {
      store.setState({ width: next });
    }
    onLayout?.(event);
  };

  return (
    <View {...rest}
      onLayout={onHostLayout}
      accessibilityLabel={rest.accessibilityLabel ?? "Data table"}
      {...{ className: joinClasses(
        "w-full min-w-0", !unstyled && "bg-surface-raised", className,
      ) }}
      style={[{ maxHeight }, style]}>
      {displayMode === "cards" ? (
        <>
          {sortingControls.length > 0 ? (
            <ScrollView horizontal style={{ flexGrow: 0, maxHeight: headerHeight + 12 }}
              contentContainerStyle={{ alignItems: "center", gap: 8, paddingVertical: 6 }}
              accessibilityLabel="Sort records">
              {sortingControls.map(header => {
                const current = header.column.getIsSorted();
                return (
                  <Pressable key={header.id}
                    accessibilityRole="button"
                    accessibilityLabel={`Sort by ${labelFor(header.column.id)}`}
                    accessibilityValue={{ text: sortValue(current) }}
                    onPress={() => header.column.toggleSorting()}
                    {...{ className: joinClasses(
                      "min-h-11 flex-row items-center gap-2 px-3",
                      !unstyled && "rounded-control border border-border bg-surface-sunken focus-visible:ring-2 focus-visible:ring-focus",
                      headerClassName,
                    ) }}>
                    <Text {...{ className: textClass }}>{labelFor(header.column.id)}</Text>
                    {current ? <Text importantForAccessibility="no" accessibilityElementsHidden
                      {...{ className: textClass }}>{current === "asc" ? "↑" : "↓"}</Text> : null}
                  </Pressable>
                );
              })}
            </ScrollView>
          ) : null}
          <FlatList data={rows} keyExtractor={row => row.id}
            contentContainerStyle={{ gap: 10, paddingVertical: 6 }}
            style={{ maxHeight: Math.max(0, maxHeight - (sortingControls.length ? headerHeight + 12 : 0)) }}
            renderItem={({ item: row }) => (
              <Pressable
                accessibilityRole={onRowPress ? "button" : undefined}
                accessibilityHint={onRowPress ? "Opens this record" : undefined}
                onPress={onRowPress ? () => onRowPress(row.original) : undefined}
                disabled={!onRowPress}
              >
                {cardRow(row)}
              </Pressable>
            )}
            ListEmptyComponent={
              <View style={{ minHeight: rowHeight, justifyContent: "center", paddingHorizontal: 12 }}>
                <Text {...{ className: textClass }}>{emptyLabel}</Text>
              </View>
            }
          />
        </>
      ) : (
        <ScrollView horizontal keyboardShouldPersistTaps="handled"
          accessibilityLabel="Table columns; scroll sideways for more columns">
          <View style={{ width: columnWidth }}>
            {table.getHeaderGroups().map(group => (
              <View key={group.id}
                {...{ className: joinClasses("flex-row", !unstyled && "border-b border-border bg-surface-sunken", headerClassName) }}
                style={{ minHeight: headerHeight }}>
                {group.headers.map(header => {
                  const sorting = sortable && header.column.getCanSort();
                  return (
                    <Pressable key={header.id} accessibilityRole={sorting ? "button" : "header"}
                      accessibilityLabel={sorting ? `Sort by ${labelFor(header.column.id)}` : labelFor(header.column.id)}
                      accessibilityValue={sorting ? { text: sortValue(header.column.getIsSorted()) } : undefined}
                      disabled={!sorting}
                      onPress={sorting ? () => header.column.toggleSorting() : undefined}
                      {...{ className: joinClasses("flex-1 min-w-0 justify-center px-3", sorting && !unstyled && "focus-visible:ring-2 focus-visible:ring-focus", cellClassName) }}>
                      {header.isPlaceholder ? null
                        : asNativeNode(flexRender(header.column.columnDef.header, header.getContext()), textClass)}
                      {header.column.getIsSorted() ? <Text importantForAccessibility="no" accessibilityElementsHidden
                        {...{ className: textClass }}>
                        {header.column.getIsSorted() === "asc" ? "↑" : "↓"}
                      </Text> : null}
                    </Pressable>
                  );
                })}
              </View>
            ))}
            <FlatList data={rows} keyExtractor={row => row.id}
              style={{ maxHeight: Math.max(0, maxHeight - headerHeight) }}
              renderItem={({ item: row }) => (
                <Pressable accessibilityRole={onRowPress ? "button" : undefined}
                  accessibilityHint={onRowPress ? "Opens this record" : undefined}
                  onPress={onRowPress ? () => onRowPress(row.original) : undefined}
                  disabled={!onRowPress}
                  {...{ className: joinClasses(
                    "flex-row", !unstyled && "border-b border-border", rowClassName,
                  ) }}
                  style={{ minHeight: rowHeight }}>
                  {row.getAllCells().map(cell => (
                    <View key={cell.id}
                      {...{ className: joinClasses("flex-1 min-w-0 justify-center px-3", cellClassName) }}>
                      {asNativeNode(flexRender(cell.column.columnDef.cell, cell.getContext()), textClass)}
                    </View>
                  ))}
                </Pressable>
              )}
              ListEmptyComponent={
                <View style={{ minHeight: rowHeight, justifyContent: "center", paddingHorizontal: 12 }}>
                  <Text {...{ className: textClass }}>{emptyLabel}</Text>
                </View>
              }
            />
          </View>
        </ScrollView>
      )}
    </View>
  );
}

/** Content layout policy. It uses the MEASURED pane, never the device family. */
export type DataTableLayout = "auto" | "table" | "cards";
export type ResolvedDataTableLayout = Exclude<DataTableLayout, "auto">;
export interface DataTableLayoutInput {
  readonly layout?: DataTableLayout;
  readonly containerWidth: number | null;
  /** A content-composition threshold, not a hardware detector. */
  readonly cardsBelow?: number;
}
export function dataTableLayout({
  layout = "auto", containerWidth, cardsBelow = 620,
}: DataTableLayoutInput): ResolvedDataTableLayout {
  if (layout === "cards" || layout === "table") return layout;
  if (layout !== "auto") throw new RangeError("Unknown table layout");
  if (!Number.isFinite(cardsBelow) || cardsBelow <= 0) throw new RangeError("Invalid table breakpoint");
  // Initial / SSR size is unknown; cards preserve every value without a
  // premature full-width or width-based device-family guess.
  if (containerWidth === null) return "cards";
  if (!Number.isFinite(containerWidth) || containerWidth < 0) {
    throw new RangeError("Invalid table host width");
  }
  return containerWidth < cardsBelow ? "cards" : "table";
}
export function tableContentWidth(
  containerWidth: number | null, columnCount: number, minColumnWidth = 144,
): number {
  if (!Number.isSafeInteger(columnCount) || columnCount < 0 ||
      !Number.isFinite(minColumnWidth) || minColumnWidth <= 0 ||
      (containerWidth !== null && (!Number.isFinite(containerWidth) || containerWidth < 0))) {
    throw new RangeError("Invalid table column geometry");
  }
  return Math.max(containerWidth ?? 0, columnCount * minColumnWidth);
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}
